        // owner equals candidateNewOwner. This holds for the correct contract for every caller; the mutant
        // allows non-owners to perform the change, so there will be inputs where caller != current owner but
        // owner becomes candidateNewOwner in the mutant. We therefore fuzz caller and candidateNewOwner and
        // invoke transferOwnership under vm.prank(caller) and assert the implication.

        // Read current owner
        address beforeOwner = c.owner();

        // Make the call as the fuzzed caller; catch reverts so we can observe whether the call succeeded
        bool ok;
        try c.transferOwnership{gas: gasleft()}(candidateNewOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // If caller was the current owner, the correct contract must allow the call and set owner == candidateNewOwner.
        // For the reference contract this must hold for all inputs; the mutant will violate because it flips the guard.
        if (caller == beforeOwner) {
            // We must perform the call as that caller to reflect correct msg.sender; use vm.prank to simulate.
            // Re-run the call under vm.prank to ensure the observed behavior corresponds to that caller.
            // Note: we earlier did an unpranked call; to ensure we tested the intended msg.sender, call under vm.prank now.
            vm.prank(caller);
            bool ok2;
            try c.transferOwnership(candidateNewOwner) {
                ok2 = true;
            } catch {
                ok2 = false;
            }
            // For the correct contract, when caller == beforeOwner, the call must succeed and owner must equal candidateNewOwner.
            // Assert that owner == candidateNewOwner (this is the single required assertTrue). The mutant will fail for some inputs
            // because it allows non-owners but would still satisfy this case when caller==owner, so to ensure the assertion
            // distinguishes, we assert the universal property: if caller==beforeOwner then after the call owner==candidateNewOwner.
