            // To ensure the test fails on the mutant for SOME inputs, we rely on fuzzing to find a scenario where prior unpranked call changed state
            // in the mutant; however the single assert must be about c's getter after interactions. We'll assert the universal implication now.

            assertTrue(c.owner() == candidateNewOwner);
        } else {
            // If caller != beforeOwner, then for the correct contract the call must revert (ok == false) and owner must remain unchanged.
            // We assert that owner did not change: owner == beforeOwner. This is also a universal property of the reference contract.
            assertTrue(c.owner() == beforeOwner);
        }
    }
}

