import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // We fuzz the attacker address so the fuzzer can find a caller that becomes owner under the mutant.
    // We need an adversarial helper that, when owned() is called, will in turn call transferOwnership on c
    // (to try to change owner). This models an external interaction that only succeeds if the onlyOwner
    // check is absent.
    function testFuzz_property(address attacker) public {
        // Keep the domain wide but exclude the zero address as a convenience (still wide).
        // This does not exclude the bug-triggering inputs in the mutant.
        if (attacker == address(0)) return;

        // Deploy helper that will attempt to seize ownership by calling transferOwnership back to attacker.
        AttackerHelper helper = new AttackerHelper(address(c));

        // Ensure helper has some ETH if needed (not required here, but harmless).
        vm.deal(address(helper), 1 ether);

        // Record owner before interaction
        address ownerBefore = c.owner();

        // Arrange for the helper to be msg.sender when calling c.owned()
        vm.prank(address(helper));
        // helper calls c.owned(); if onlyOwner modifier is present, this call should revert (or at least not allow the helper
        // to call transferOwnership). The helper's attempt to call transferOwnership will only succeed if the onlyOwner check is removed.
        // We ignore any revert from c.owned(); we only observe the resulting owner.
        try helper.triggerOwned(attacker) {
            // no-op
        } catch {
            // ignore revert
        }

        // Exactly one assertion: in the correct contract, owner must remain unchanged for any attacker address.
        // The mutant that removed the require allows the helper (non-owner) to call through and change owner to `attacker` for some fuzzed inputs.
        assertTrue(c.owner() == ownerBefore);
    }
}

// Adversarial helper: calls c.owned() (as msg.sender) and inside that call attempts to seize ownership by calling transferOwnership.
contract AttackerHelper {
    C immutable target;
    constructor(address _target) { target = C(_target); }

    // Called by the test via vm.prank(helper) to make this contract the msg.sender to c.owned()
    function triggerOwned(address to) external {
        // Call owned() on target. If the onlyOwner modifier is missing, the helper's internal logic
        // will attempt to call transferOwnership to set owner to `to`.
        // We perform the attempted takeover after calling owned(), but to ensure the helper's behaviour
        // occurs during the same external call chain, we implement ownedCall which calls owned() and then
        // (in the same tx flow) calls transferOwnership. This simulates an adversary that uses the
        // unlocked modifier to perform owner-changing calls.
        target.owned();
        // Try to seize ownership. If onlyOwner is present, this will revert; if removed, this will succeed.
        target.transferOwnership(to);
    }
}

